 const [menuOpen,setMenuOpen]=useState(false); const [tab,setTab]=useState('Overview');const [question,setQuestion]=useState('');const [conversationId,setConversationId]=useState('');const [messages,setMessages]=useState<Entry[]>([]);const [hist,setHist]=useState<{id:string;title:string;bot_id:string}[]>([]);
