 {tab==='Company Profile'&&<section className="card"><h2>{companyId?'Edit company profile':'Create your company'}</h2><p className="muted">Brand, contact, hours and policies can become searchable chatbot knowledge after indexing.</p><div className="grid">{field('Company name',companyForm.name,v=>setCompanyForm(s=>({...s,name:v})))}{field('Industry / domain',companyForm.industry,v=>setCompanyForm(s=>({...s,industry:v})))}{field('Website',companyForm.website,v=>setCompanyForm(s=>({...s,website:v})))}{field('Phone',companyForm.phone,v=>setCompanyForm(s=>({...s,phone:v})))}{field('Address',companyForm.address,v=>setCompanyForm(s=>({...s,address:v})))}{field('Operating hours',companyForm.hours,v=>setCompanyForm(s=>({...s,hours:v})))}</div>{field('About company / services',companyForm.description,v=>setCompanyForm(s=>({...s,description:v})),3)}{field('Policies / shipping / returns / FAQs',companyForm.policies,v=>setCompanyForm(s=>({...s,policies:v})),4)}<div className="actions"><button disabled={busy||!companyForm.name.trim()} onClick={()=>perform(async()=>{if(companyId){await request(`/api/companies/${companyId}`,'PATCH',companyForm)}else{const c=await request('/api/companies','POST',companyForm);setCompanyId(c.id);setCompanyForm(c)}await refresh()},'Company saved')}>{companyId?'Save profile':'Create company'}</button>{companyId&&kbId&&<button className="secondary" disabled={busy} onClick={()=>perform(()=>request(`/api/companies/${companyId}/sync-profile?kb_id=${kbId}`,'POST'),'Company profile indexed for search')}>Sync profile into selected knowledgebase</button>}</div></section>}
